from pathlib import Path
p=Path('index.html'); s=p.read_text(encoding='utf-8')
def once(old,new,label):
 global s
 n=s.count(old)
 if n!=1: raise SystemExit(f'{label}: expected 1 anchor, got {n}')
 s=s.replace(old,new,1)
CSS='  /* 의미 돌아보기 — 공허감은 0~4의 다섯 단계만 사용합니다.\n     컷오프·위험색·판정 문구 없이, 그날의 자기평정만 남깁니다. */\n  .mn-empty{display:grid;grid-template-columns:repeat(5,1fr);gap:7px}\n  .mn-empty button{padding:9px 0;border:1.5px solid var(--line);border-radius:12px;background:var(--panel);color:var(--dim)}\n  .mn-empty button.on{border-color:var(--acc);background:var(--accbg);color:var(--acc);font-weight:700}\n  .mn-line-opt{display:block;width:100%;text-align:left;padding:11px 12px;border:1px solid var(--line);border-radius:11px;margin-top:8px;line-height:1.55}\n  .mn-line-opt.on{border-color:var(--acc);background:var(--accbg);color:var(--acc)}\n  .mn-day{display:flex;gap:10px;padding:11px 0;border-top:1px solid var(--line)}\n  .mn-day:first-child{border-top:none}\n  .mn-day .d{flex:0 0 128px;font-size:12px;color:var(--dim);line-height:1.6;white-space:nowrap}\n  .mn-day .c{flex:1;min-width:0;font-size:13.5px;line-height:1.6;word-break:break-word}\n  .mn-day .c em{font-style:normal;color:var(--faint);font-size:12px;margin-right:4px}\n\n'
