once('    <h2>실천하기</h2>\n    <button class="toolcard hide" id="tool-family-tools">','    <h2>실천하기</h2>\n    <button class="toolcard" id="tool-meaning">\n      <span class="ic" data-ico="sprout"></span><span class="b"><b>의미 돌아보기</b><span id="tool-meaning-s">오늘의 경험에서 나에게 중요한 것을 돌아보기</span></span><span class="go">열기</span>\n    </button>\n    <button class="toolcard hide" id="tool-family-tools">','tool card')
SECTION='<!-- ══════════ 의미 돌아보기 V9.0.11 · 하루 한 장 ══════════\n     ★ 당사자 모드에서만 사용합니다. 가족모드 기록과 섞지 않습니다.\n     ★ 진입은 회복도구와 하루 마무리 두 곳이지만 저장은 S.wbDays[날짜] 한 곳입니다.\n     ★ 필수 항목은 없고, 아무것도 남기지 않으면 빈 기록을 만들지 않습니다. -->\n<section class="pg" id="p-meaning">\n  <div class="sp" style="margin-bottom:11px">\n    <h1 style="margin:0">의미 돌아보기</h1>\n    <button class="tiny" style="color:var(--acc);font-weight:600" data-smart-back data-back-default="tools" data-back-label="회복도구" onclick="appBack(\'tools\')">← 회복도구</button>\n  </div>\n  <div class="note" style="margin-bottom:12px">오늘의 경험에서 아팠던 것, 남아 있던 힘, 내가 지킨 것을 짧게 돌아봅니다.<br><b id="mn-date"></b></div>\n  <div class="card"><h3>오늘의 공허감 <span class="tiny" style="font-weight:400">(선택)</span></h3><p class="muted" style="margin:-4px 0 10px">0은 그런 느낌 없음, 4는 많이 느껴짐입니다. 컷오프나 판정은 없습니다.</p><div class="mn-empty" id="mn-empty"></div><div style="height:8px"></div><button class="btn ghost sm" id="mn-empty-skip" style="display:none">답하지 않음</button></div>\n  <div class="card"><h3>오늘 아팠던 것은</h3><p class="muted" style="margin:-4px 0 10px">여러 개를 골라도 됩니다. 없으면 건너뛰어도 됩니다.</p><div class="opts" id="mn-hard"></div><textarea id="mn-hard-note" maxlength="180" placeholder="칩에 없으면 직접 적기 (선택)" style="margin-top:10px;min-height:58px"></textarea></div>\n  <div class="card"><h3>그럼에도 남아 있던 힘은</h3><p class="muted" style="margin:-4px 0 10px">버틴 것, 연결된 사람, 도움을 요청한 것도 힘입니다.</p><div class="opts" id="mn-strength"></div><textarea id="mn-strength-note" maxlength="180" placeholder="나에게 남아 있던 힘을 직접 적기 (선택)" style="margin-top:10px;min-height:58px"></textarea></div>\n  <div class="card"><h3>오늘 선택하거나 지킨 것은</h3><p class="muted" style="margin:-4px 0 10px">작은 행동도 괜찮습니다. 통계는 선택한 칩만 셉니다.</p><div class="opts" id="mn-action"></div><textarea id="mn-action-note" maxlength="180" placeholder="칩에 없으면 직접 적기 (선택)" style="margin-top:10px;min-height:58px"></textarea></div>\n  <div class="card"><h3>삶이 나에게 요청한 것은 <span class="tiny" style="font-weight:400">(선택)</span></h3><textarea id="mn-request" maxlength="240" placeholder="지금의 삶이 나에게 묻거나 요청하는 것이 있다면 짧게 적어보세요"></textarea><p class="tiny" style="margin:8px 0 0">직접 적은 글은 앱이 자동 분류하거나 점수화하지 않습니다.</p></div>\n  <div class="card" id="mn-line-card"><h3>오늘의 문장 <span class="tiny" style="font-weight:400">(선택)</span></h3><p class="muted" style="margin:-4px 0 8px">내 회복영역에 맞는 후보를 세 문장씩 보여드립니다. 마음에 남는 문장이 있을 때만 고르세요.</p><div id="mn-lines"></div><button class="btn ghost sm" id="mn-lines-more" style="margin-top:9px">다른 문장 보기</button></div>\n  <button class="btn" id="mn-save">저장하기</button><div style="height:9px"></div><button class="btn ghost" id="mn-clear" style="display:none;color:var(--bad);border-color:var(--bad)">오늘 기록 지우기</button>\n  <div class="sep"></div><h2 style="font-size:15px;margin:0 0 9px">지난 기록</h2><div class="card" style="padding-top:4px;padding-bottom:4px"><div id="mn-list"></div></div><button class="btn ghost sm" id="mn-more" style="display:none"></button>\n  <p class="tiny" style="margin:12px 0 0">이 기록은 이 기기 안에만 남습니다. 서버나 마음프로로 자동 전송하지 않습니다.</p>\n</section>\n\n'
